package org.agentos.memory;
import android.app.Instrumentation;
import android.os.Bundle;
import org.json.*;

/** Real SQLite queue, fake clock/answers only in the isolated, differently signed test APK. */
public final class QueueTests extends Instrumentation {
 int checks;MemoryStore s;long now;int sequence;
 void check(boolean b,String label){checks++;if(!b)throw new AssertionError(label);}
 JSONObject add(String source)throws Exception{return s.ingest(source,"page","Queue fixture","Synthetic queue record "+(++sequence)+": tomorrow at 18:00, source-labelled reference.",s.config().getLong("generation"));}
 void add(int count)throws Exception{for(int i=0;i<count;i++)check(add("org.agentos.memorytests")!=null,"local record saved");}
 JSONObject answers(JSONObject batch)throws Exception{JSONObject a=new JSONObject();String[] categories={"work","life","travel","learn","other"};for(int i=0;i<batch.getJSONArray("items").length();i++){String p="r"+i+"_";a.put(p+"category",new JSONObject().put("choice",categories[i%5]));a.put(p+"importance",new JSONObject().put("noul",.8));a.put(p+"next_step",new JSONObject().put("choice","organize").put("confidence",.9));}return a;}
 int queued()throws Exception{return s.status().getInt("analysisQueued");}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{
  getTargetContext().deleteDatabase("memories.db");getTargetContext().getSharedPreferences("memory",0).edit().clear().commit();s=new MemoryStore(getTargetContext(),()->{});now=System.currentTimeMillis();
  s.configure(new JSONObject().put("enabled",true).put("model","model-A").put("sources",new JSONArray().put("org.agentos.memorytests").put("org.synthetic.other")));
  check(!s.config().getBoolean("analysisEnabled"),"analysis opt-in independent from capture and model selection");
  add(3);check(queued()==3,"all local saves durably queued while off");check(s.claimBatch(now+21000)==null,"off means no request");check(s.status().getLong("analysisBatchAttempts")==0,"no hidden analysis attempt");
  s.configure(new JSONObject().put("analysisEnabled",true));check(s.claimBatch(now)==null,"coalesce before first request");now+=22000;
  JSONObject first=s.claimBatch(now);check(first.getJSONArray("items").length()==3,"three records in one request");check(s.status().getLong("analysisBatchAttempts")==1,"one budget unit for batch");check(s.claimBatch(now+16000)==null,"leased records not dispatched twice");
  s.completeBatch(first,answers(first));check(queued()==0,"batch completion drains all records");
  String[] labels={"工作","生活","出行"};for(int i=0;i<3;i++)check(s.read(first.getJSONArray("items").getJSONObject(i).getString("id"),false).getString("category").equals(labels[i]),"answer mapped to immutable record order");
  add(7);now+=30000;JSONObject five=s.claimBatch(now);check(five.getJSONArray("items").length()==5,"batch bounded to five");check(s.claimBatch(now+1000)==null&&queued()==7,"rate limit retains all members");s.completeBatch(five,answers(five));check(queued()==2,"overflow remains queued");now+=16000;JSONObject two=s.claimBatch(now);check(two.getJSONArray("items").length()==2,"overflow automatically eligible later");s.completeBatch(two,answers(two));check(queued()==0,"second batch drains overflow");
  add(2);s.prefs.edit().putLong("analysisHourStart",now).putInt("analysisCount",60).commit();check(s.claimBatch(now+30000)==null&&queued()==2,"hour quota never drops queue");now+=3600001;JSONObject afterHour=s.claimBatch(now);check(afterHour!=null,"hour budget resets and backlog resumes");s.completeBatch(afterHour,answers(afterHour));
  add(2);now+=30000;JSONObject failing=s.claimBatch(now);s.retryBatch(failing.getString("token"),now);check(queued()==2,"network failure retains both");check(s.claimBatch(now+29000)==null,"failure backs off");add(1);JSONObject fresh=s.claimBatch(now+16000);check(fresh.getJSONArray("items").length()==1,"fresh records cannot pull retries out of backoff early");s.completeBatch(fresh,answers(fresh));now+=32000;JSONObject retried=s.claimBatch(now);check(retried.getJSONArray("items").length()==2,"failed batch rejoined later");s.completeBatch(retried,answers(retried));
  add(2);now+=30000;JSONObject inFlight=s.claimBatch(now);s.configure(new JSONObject().put("analysisEnabled",false));check(queued()==2,"disable keeps backlog");s.completeBatch(inFlight,answers(inFlight));check(queued()==2,"disabled late result cannot consume backlog");add(1);s.configure(new JSONObject().put("analysisEnabled",true));now+=30000;JSONObject resumed=s.claimBatch(now);check(resumed.getJSONArray("items").length()==3,"re-enable combines old and new records");s.completeBatch(inFlight,answers(inFlight));check(queued()==3,"old token cannot consume new lease");s.completeBatch(resumed,answers(resumed));
  add(2);now+=30000;JSONObject oldModel=s.claimBatch(now);s.configure(new JSONObject().put("model","model-B"));s.completeBatch(oldModel,answers(oldModel));check(queued()==2,"model switch rejects old result without loss");now+=30000;JSONObject newModel=s.claimBatch(now);check(newModel.getString("model").equals("model-B"),"backlog uses current model");s.completeBatch(newModel,answers(newModel));
  add(2);now+=30000;JSONObject recordPause=s.claimBatch(now);s.configure(new JSONObject().put("enabled",false).put("proactive",false));check(s.config().getBoolean("analysisEnabled"),"capture pause does not switch off analysis");s.completeBatch(recordPause,answers(recordPause));check(queued()==0,"recording pause does not discard in-flight analysis");check(add("org.agentos.memorytests")==null,"capture pause still blocks new local captures");s.configure(new JSONObject().put("enabled",true));
  JSONObject corrected=add("org.agentos.memorytests"),deleted=add("org.agentos.memorytests"),excluded=add("org.synthetic.other");now+=30000;JSONObject removed=s.claimBatch(now);s.update(corrected.getString("id"),1,"Corrected","User-corrected synthetic evidence must remain unchanged.");s.forget(deleted.getString("id"));s.configure(new JSONObject().put("sources",new JSONArray().put("org.agentos.memorytests")));s.completeBatch(removed,answers(removed));check(queued()==0,"correction deletion exclusion remove queued work");check(s.read(corrected.getString("id"),false).getString("analysis").equals("corrected"),"late model cannot overwrite correction");
  add(2);now+=30000;JSONObject crashed=s.claimBatch(now);s.close();s=new MemoryStore(getTargetContext(),()->{});check(queued()==2,"queue and lease survive process recreation");check(s.claimBatch(now+20000)==null,"live lease not replayed after restart");now+=120001;JSONObject recovered=s.claimBatch(now);check(recovered.getJSONArray("items").length()==2,"expired lease recovered after restart");s.completeBatch(recovered,answers(recovered));check(queued()==0,"recovered batch drains");
  add(2);now+=30000;JSONObject invalid=s.claimBatch(now);boolean rejected=false;try{s.completeBatch(invalid,new JSONObject());}catch(Exception expected){rejected=true;}check(rejected&&queued()==2,"malformed answer cannot partially consume queue");s.retryBatch(invalid.getString("token"),now);now+=31000;JSONObject valid=s.claimBatch(now);s.completeBatch(valid,answers(valid));
  JSONObject pending=add("org.agentos.memorytests");String pid=pending.getString("id");s.getWritableDatabase().execSQL("DROP TABLE analysis_queue");s.getWritableDatabase().setVersion(1);s.prefs.edit().remove("analysisEnabled").commit();s.close();s=new MemoryStore(getTargetContext(),()->{});check(s.getReadableDatabase().getVersion()==3,"v1 database migrated in place");check(s.read(pid,false).getString("body").equals(pending.getString("body")),"migration preserves original body");check(!s.config().getBoolean("analysisEnabled"),"legacy model selection does not opt into new analysis");check(queued()==1,"migration queues only unfinished records");
  result.putString("result",new JSONObject().put("passed",true).put("checks",checks).toString());finish(-1,result);
 }catch(Throwable t){android.util.Log.e("TakuMemoryTest","failure",t);StringBuilder st=new StringBuilder(t.toString());StackTraceElement[] e=t.getStackTrace();for(int i=0;i<Math.min(12,e.length);i++)st.append(" @ ").append(e[i].getClassName().replace("org.agentos.memory.","")).append(".").append(e[i].getMethodName()).append(":").append(e[i].getLineNumber());result.putString("failure",st.toString());finish(0,result);}}
}
